 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] != 0:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            colors = {grid[y][x] for y, x in cells}
            boxes = {}
            for color in colors:
                pts = [(y, x) for y, x in cells if grid[y][x] == color]
                boxes[color] = (max(y for y, x in pts)-min(y for y, x in pts)+1) * (max(x for y, x in pts)-min(x for y, x in pts)+1)
            ordered = sorted(colors, key=lambda color: boxes[color], reverse=True)
            mapping = {old: new for old, new in zip(ordered, reversed(ordered))}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
